9	impl FormatNodeRule<MdFencedCodeBlock> for FormatMdFencedCodeBlock {
10	    fn fmt_fields(&self, node: &MdFencedCodeBlock, f: &mut MarkdownFormatter) -> FormatResult<()> {
11	        let MdFencedCodeBlockFields {
12	            l_fence,
13	            r_fence,
14	            r_fence_indent,
15	            content,
16	            code_list,
17	            indent,
18	        } = node.as_fields();
19	
20	        let l_fence = l_fence?;
21	        let fence_text = l_fence.text();
22	        // SAFETY: fence_text has at least one character.
23	        let fence_char = fence_text.as_bytes()[0] as char;
24	
25	        // Compute the minimum fence length needed (CommonMark §4.5).
26	        // The fence must be strictly longer than any same-character sequence
27	        // in the content, otherwise the inner sequence would be parsed as a
28	        // closing fence. E.g. if the content contains ``` (3 backticks),
29	        // the outer fence needs at least 4.
30	        let max_inner = longest_fence_char_sequence(node, fence_char);
31	        let fence_len = (max_inner + 1).max(3);
32	        let normalized_fence: String = std::iter::repeat_n(fence_char, fence_len).collect();
33	
34	        write!(
35	            f,
36	            [
37	                indent.format(),
38	                format_replaced(
39	                    &l_fence,
40	                    &text(&normalized_fence, l_fence.text_trimmed_range().start())
41	                ),
42	                code_list.format(),
43	                hard_line_break(),
44	                content
45	                    .format()
46	                    .with_options(FormatMdFormatInlineItemListOptions {
47	                        print_mode: TextPrintMode::Clean,
48	                        keep_fences_in_italics: false
49	                    }),
50	                hard_line_break(),
51	                r_fence_indent.format(),
52	            ]
53	        )?;
54	
55	        if let Ok(r_fence) = r_fence {
56	            write!(
57	                f,
58	                [format_replaced(
59	                    &r_fence,
60	                    &text(&normalized_fence, r_fence.text_trimmed_range().start())
61	                )]
62	            )?;
63	        }
64	
65	        Ok(())
66	    }
67	}
