22	impl Format<MarkdownFormatContext> for FormatMarkdownVerbatimNode<'_> {
23	    fn fmt(&self, f: &mut Formatter<MarkdownFormatContext>) -> FormatResult<()> {
24	        // Track all tokens in the node so the formatter knows they've been seen
25	        for element in self.node.descendants_with_tokens(Direction::Next) {
26	            match element {
27	                SyntaxElement::Token(token) => {
28	                    // Bypass `assert_all_tracked` in
29	                    // https://github.com/biomejs/biome/blob/79d2e7b0f08b9f8ee4286ba15f9b4b8b1a5d1f52/crates/biome_formatter/src/printed_tokens.rs#L71-L81
30	                    f.state_mut().track_token(&token);
31	                }
32	                SyntaxElement::Node(node) => {
33	                    // Mark that we've checked suppression comments for this node
34	                    // to bypass `assert_checked_all_suppressions`
35	                    // in https://github.com/biomejs/biome/blob/79d2e7b0f08b9f8ee4286ba15f9b4b8b1a5d1f52/crates/biome_formatter/src/comments.rs#L965-L975
36	                    let comments = f.context().comments();
37	                    comments.mark_suppression_checked(&node);
38	                }
39	            }
40	        }
41	
42	        // Write the original source text as-is
43	        text(
44	            &self.node.to_string(),
45	            self.node.text_trimmed_range().start(),
46	        )
47	        .fmt(f)
48	    }
49	}
