+use biome_rowan::{Direction, SyntaxElement};
+
+#[derive(Debug, Clone, Default)]
+pub(crate) struct FormatMdFencedCodeBlock;
+impl FormatNodeRule<MdFencedCodeBlock> for FormatMdFencedCodeBlock {
+    fn fmt_fields(&self, node: &MdFencedCodeBlock, f: &mut MarkdownFormatter) -> FormatResult<()> {
+        let MdFencedCodeBlockFields {
+            l_fence,
+            r_fence,
+            r_fence_indent,
+            content,
+            code_list,
+            indent,
+        } = node.as_fields();
+
+        let l_fence = l_fence?;
+
+        // The output always uses backtick-style fences, regardless of whether
+        // the source used backticks (```) or tildes (~~~ / ~~~~).
+        let fence_char = '`';
+
+        // Compute the minimum fence length needed (CommonMark §4.5).
+        // The fence must be strictly longer than any backtick sequence in the
+        // content, otherwise the inner sequence would be parsed as a closing
+        // fence. E.g. if the content contains ``` (3 backticks), the outer
+        // fence needs at least 4. Only backtick sequences are counted, since
+        // the output fence is always backticks — tilde sequences in the
+        // content can never be confused with a backtick fence.
+        let max_inner = longest_fence_char_sequence(node, fence_char);
+        let fence_len = (max_inner + 1).max(3);
+        let normalized_fence: String = std::iter::repeat_n(fence_char, fence_len).collect();
+
+        // Build the info string, preserving its internal structure (commas and
+        // multiple space-separated values) while trimming surrounding
+        // whitespace. It is emitted immediately after the fence, with no
+        // separating space between the fence characters and the info string.
+        let info_string = code_list.syntax().text_trimmed().to_string();
+        let info_string = info_string.trim();
+        // The info string is emitted as raw text below, so replicate the
+        // bookkeeping `code_list.format()` would otherwise perform: mark the
+        // tokens as tracked and their nodes as suppression-checked.
+        for element in code_list.syntax().descendants_with_tokens(Direction::Next) {
+            match element {
+                SyntaxElement::Token(token) => {
+                    f.state_mut().track_token(&token);
+                }
+                SyntaxElement::Node(node) => {
+                    f.context().comments().mark_suppression_checked(&node);
+                }
+            }
+        }
+
+        write!(
+            f,
+            [
+                indent.format(),
+                format_replaced(
+                    &l_fence,
+                    &text(&normalized_fence, l_fence.text_trimmed_range().start())
+                ),
+            ]
+        )?;
+
+        if !info_string.is_empty() {
+            write!(
+                f,
+                [text(
+                    info_string,
+                    code_list.syntax().text_trimmed_range().start()
+                )]
+            )?;
+        }
+
+        write!(
+            f,
+            [
+                hard_line_break(),
+                content
+                    .format()
+                    .with_options(FormatMdFormatInlineItemListOptions {
+                        print_mode: TextPrintMode::Clean,
+                        keep_fences_in_italics: false
+                    }),
+                hard_line_break(),
+                r_fence_indent.format(),
+            ]
+        )?;
+
+        if let Ok(r_fence) = r_fence {
+            write!(
+                f,
+                [format_replaced(
+                    &r_fence,
+                    &text(&normalized_fence, r_fence.text_trimmed_range().start())
+                )]
+            )?;
+        }
+
+        Ok(())
+    }
+}
